  // Canonical topic order for the Sources tab — also fixes the numbering every [n] chip uses,
  // so footnote numbers always match the order references appear in the bibliography.
  const TOPIC_ORDER = ['BMI', 'Children', 'BMR', 'TDEE', 'Dynamics', 'Body fat', 'Adiposity', 'Guidelines', 'Nutrition', 'Activity', 'Sleep & behavior', 'Outcomes'];

  // Compact labels for citation chips (defaults to the part of `short` before any parenthesis).
  const TAGS = {
    nasem2023: 'NASEM 2023', fao2004: 'FAO/WHO/UNU 2004', who2004asia: 'WHO 2004', rubino2025: 'Lancet Comm. 2025',
    jensen2014: 'AHA/ACC/TOS 2013', espghan2005: 'ESPGHAN 2005', niddkGallstones: 'NIDDK', who2008waist: 'WHO 2008',
    idf2006: 'IDF (Alberti 2005)', efsa2010water: 'EFSA 2010', who2020pa: 'WHO 2020', who2019u5: 'WHO 2019', donnelly2009: 'ACSM 2009',
    lean2018: 'DiRECT 2018', cdc2022ext: 'CDC 2022', cdc2000: 'CDC 2000', who2006: 'WHO 2006', hampl2023: 'AAP 2023',
    barlow2007: 'Barlow 2007', nice2025: 'NICE 2025', nice2006: 'NICE CG32', cdcWhoSas: 'CDC (WHO SAS)', who2000: 'WHO 2000', schofield1985: 'Schofield 1985',
    cunningham1991: 'Cunningham 1991', iom2005: 'IOM 2005', bauer2013: 'PROT-AGE 2013', harris1918: 'Harris-Benedict 1918',
    frankenfield2011: 'Frankenfield 2011', hall2019upf: 'Hall 2019 (UPF)', patel2006: 'Patel 2006',
    murphy2022: 'Murphy 2022', tasali2022: 'Tasali 2022', nedeltcheva2010: 'Nedeltcheva 2010', mifflin1990: 'Mifflin 1990', owen1986: 'Owen 1986', owen1987: 'Owen 1987',
    livingston2005: 'Livingston 2005', hodgdon1984: 'Hodgdon 1984', woolcott2018: 'Woolcott 2018', woolcott2019: 'Woolcott 2019',
    gomezambrosi2012: 'Gómez-Ambrosi 2012', oneill2023: "O'Neill 2023", vilargomez2015: 'Vilar-Gomez 2015', nhlbi1998: 'NHLBI 1998',
  };
  for (const [id, r] of Object.entries(R)) { r.id = id; r.tag = TAGS[id] || r.short.split(' (')[0]; }

  // Group by topic in TOPIC_ORDER, then number 1..N in that same order — this is what the
  // Sources tab renders, and what every [n] chip elsewhere in the app links to.
  const byTopic = {};
  for (const r of Object.values(R)) (byTopic[r.topic] = byTopic[r.topic] || []).push(r);
  const orderedTopics = TOPIC_ORDER.filter((t) => byTopic[t]).map((t) => ({ topic: t, items: byTopic[t] }));
  let n = 1;
  for (const grp of orderedTopics) for (const r of grp.items) r.num = n++;

  function get(id) {
    const r = R[id];
    if (!r) throw new Error('Unknown reference: ' + id);
    return r;
  }

  return { all: R, get, orderedTopics, count: n - 1 };
